    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_560595fbde",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_aa2f56bbb7",
        "localizador": "L03"
      }
    ],
    "lacunas": [
      "O valor de eventual extensão depende de o marco final ultrapassar D10 e de quantos dias corridos isso ocorrer; o novo término é indeterminado."
    ],
    "motivo": "O custo inclui a cobrança adicional de R$ 150,00; eventual cobrança por extensão não pode ser calculada sem o término novo.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
